@Test
public void testMixedCaseLiterals() throws IOException {
  JsonReader reader = new JsonReader(reader("[True,TruE,False,FALSE,NULL,nulL]"));
  reader.beginArray();
  assertThat(reader.nextBoolean()).isTrue();
  assertThat(reader.nextBoolean()).isTrue();
  assertThat(reader.nextBoolean()).isFalse();
  assertThat(reader.nextBoolean()).isFalse();
  reader.nextNull();
  reader.nextNull();
  reader.endArray();
  assertThat(reader.peek()).isEqualTo(JsonToken.END_DOCUMENT);
}

proposals.refactored:
// Helper to create a fresh JsonReader positioned at the start of the array.
private JsonReader newReader() throws IOException {
  JsonReader reader = new JsonReader(reader("[True,TruE,False,FALSE,NULL,nulL]"));
  reader.beginArray();
  return reader;
}

@Test
public void testMixedCaseLiterals_trueLiterals() throws IOException {
  JsonReader reader = newReader();

  assertThat(reader.nextBoolean())
      .named("First literal 'True' should be true")
      .isTrue();
  assertThat(reader.nextBoolean())
      .named("Second literal 'TruE' should be true")
      .isTrue();

  // Skip remaining values to reach end of array.
  reader.skipValue(); // False
  reader.skipValue(); // FALSE
  reader.skipValue(); // NULL
  reader.skipValue(); // nulL

  reader.endArray();
  assertThat(reader.peek())
      .named("Reader should be at END_DOCUMENT after consuming the array")
      .isEqualTo(JsonToken.END_DOCUMENT);
}

@Test
public void testMixedCaseLiterals_falseLiterals() throws IOException {
  JsonReader reader = newReader();

  // Skip true literals.
  reader.skipValue(); // True
  reader.skipValue(); // TruE

  assertThat(reader.nextBoolean())
      .named("Third literal 'False' should be false")
      .isFalse();
  assertThat(reader.nextBoolean())
      .named("Fourth literal 'FALSE' should be false")
      .isFalse();

  // Skip remaining values to reach end of array.
  reader.skipValue(); // NULL
  reader.skipValue(); // nulL

  reader.endArray();
  assertThat(reader.peek())
      .named("Reader should be at END_DOCUMENT after consuming the array")
      .isEqualTo(JsonToken.END_DOCUMENT);
}

@Test
public void testMixedCaseLiterals_nullLiterals() throws IOException {
  JsonReader reader = newReader();

  // Skip non‑null literals.
  reader.skipValue(); // True
  reader.skipValue(); // TruE
  reader.skipValue(); // False
  reader.skipValue(); // FALSE

  assertThat(reader.peek())
      .named("Fifth literal should be a NULL token")
      .isEqualTo(JsonToken.NULL);
  reader.nextNull();

  assertThat(reader.peek())
      .named("Sixth literal should be a NULL token")
      .isEqualTo(JsonToken.NULL);
  reader.nextNull();

