/**
 * Creates a JsonReader configured for lenient parsing.
 *
 * @param json the JSON source string
 * @return a JsonReader with Strictness.LENIENT applied
 * @throws IOException if an I/O error occurs while creating the reader
 */
private JsonReader createLenientReader(String json) throws IOException {
    JsonReader reader = new JsonReader(reader(json));
    reader.setStrictness(Strictness.LENIENT);
    return reader;
}

