private static class JsonWriterSetup {
    final StringWriter stringWriter;
    final JsonWriter jsonWriter;

    JsonWriterSetup(StringWriter stringWriter, JsonWriter jsonWriter) {
        this.stringWriter = stringWriter;
        this.jsonWriter = jsonWriter;
    }
}

/**
 * Common setup for tests that need a JsonWriter started with an opened array.
 */
private JsonWriterSetup setupTestNulls() throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.beginArray();
    return new JsonWriterSetup(stringWriter, jsonWriter);
}

/**
 * Verifies that writing a null value produces the expected token.
 */
@Test
public void testNulls_NullValue() throws IOException {
    JsonWriterSetup ctx = setupTestNulls();
    ctx.jsonWriter.nullValue();
    ctx.jsonWriter.endArray();
    String actualJson = ctx.stringWriter.toString();
    assertThat(actualJson).contains("null");
}

/**
 * Verifies that closing an array without any elements yields an empty JSON array.
 */
@Test
public void testNulls_ArrayClosure() throws IOException {
    JsonWriterSetup ctx = setupTestNulls();
    ctx.jsonWriter.endArray();
    String actualJson = ctx.stringWriter.toString();
    assertThat(actualJson).isEqualTo("[]");
}

