public void testRoundTrip() {
    String base = "<!DOCTYPE html>";
    assertEquals("HTML output should convert DOCTYPE to lowercase for base case", "<!doctype html>", htmlOutput(base));
    assertEquals("XML output should preserve original DOCTYPE for base case", base, xmlOutput(base));

    String publicDoc = "<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">";
    assertEquals("HTML output should preserve public DOCTYPE declaration", publicDoc, htmlOutput(publicDoc));
    assertEquals("XML output should preserve public DOCTYPE declaration", publicDoc, xmlOutput(publicDoc));

    String systemDoc = "<!DOCTYPE html SYSTEM \"exampledtdfile.dtd\">";
    assertEquals("HTML output should preserve system DOCTYPE declaration", systemDoc, htmlOutput(systemDoc));
    assertEquals("XML output should preserve system DOCTYPE declaration", systemDoc, xmlOutput(systemDoc));

    String legacyDoc = "<!DOCTYPE html SYSTEM \"about:legacy-compat\">";
    assertEquals("HTML output should preserve legacy system DOCTYPE declaration", legacyDoc, htmlOutput(legacyDoc));
    assertEquals("XML output should preserve legacy system DOCTYPE declaration", legacyDoc, xmlOutput(legacyDoc));
}

