/**
 * Helper to copy a class‑path resource into the provided temporary directory.
 */
private File copyResourceToTempDir(String resourceName, File tempDir) throws Exception {
    URL resource = ParseTest.class.getResource(resourceName);
    if (resource == null) {
        throw new IllegalStateException("Resource not found: " + resourceName);
    }
    Path source = Paths.get(resource.toURI());
    Path target = tempDir.toPath().resolve(Paths.get(resourceName).getFileName());
    Files.copy(source, target, StandardCopyOption.REPLACE_EXISTING);
    return target.toFile();
}

/*------------------------------ Test methods ------------------------------*/

