    File in = copyResourceToTempDir("/htmltests/news-com-au-home.html", tempDir);
    assertTrue("Input HTML file must exist and be a regular file before parsing",
               in.exists() && in.isFile());

    var doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");
    assertEquals("Document title should match expected",
                 "News.com.au | News from Australia and around the world online | NewsComAu",
                 doc.title());
}

