/**
 * Parameterized test for {@link Element#hasClass(String)} covering both positive and negative cases.
 */
@ParameterizedTest(name = "{index} => classAttr=''{0}'', queryClass=''{1}'', expected={2}")
@CsvSource({
    // Positive matches for class "toto"
    "'toto','toto',true",
    "' toto','toto',true",
    "'toto ','toto',true",
    "'\\ttoto ','toto',true",
    "'  toto ','toto',true",
    // Negative matches for class "toto"
    "'ab','toto',false",
    "'     ','toto',false",
    "'tototo','toto',false",
    // Positive matches for class "raulpismuth"
    "'raulpismuth  ','raulpismuth',true",
    "' abcd  raulpismuth efgh ','raulpismuth',true",
    "' abcd efgh raulpismuth','raulpismuth',true",
    "' abcd efgh raulpismuth ','raulpismuth',true"
})
void testHasClassDomMethods(String classAttr, String queryClass, boolean expected) {
    Element el = createElementWithClass(classAttr);
    boolean hasClass = el.hasClass(queryClass);
    assertEquals(expected, hasClass,
        "Class '" + queryClass + "' detection with attribute value '" + classAttr + "' expected " + expected);
}

