private static class TextBeanContext {
    Document doc;
    Element p;
    Element span;
    TextNode spanTextNode;
    TextNode tn;
}

// Shared setup extracting common document parsing and element selection
private TextBeanContext setupTestTextBean() {
    TextBeanContext ctx = new TextBeanContext();
    ctx.doc = Jsoup.parse("<p>One <span>two &amp;</span> three &amp;</p>");
    ctx.p = ctx.doc.select("p").first();
    ctx.span = ctx.doc.select("span").first();
    ctx.spanTextNode = (TextNode) ctx.span.childNode(0);
    ctx.tn = (TextNode) ctx.p.childNode(2);
    return ctx;
}

// Helper to mutate the paragraph TextNode's text
private void mutateParagraphTextNode(TextBeanContext ctx) {
    ctx.tn.text(" POW!");
}

// Helper to set an attribute on the paragraph TextNode
private void setTextNodeAttribute(TextBeanContext ctx) {
    ctx.tn.attr(ctx.tn.nodeName(), "kablam &");
}

