    assertEquals(" POW!", ctx.tn.text());
}

@Test
public void testTextBean_ParagraphHtmlAfterSetText() {
    TextBeanContext ctx = setupTestTextBean();
    mutateParagraphTextNode(ctx);
    assertEquals("One <span>two &amp;</span> POW!", TextUtil.stripNewlines(ctx.p.html()));
}

