private static final int EXPECTED_FORM_DATA_COUNT = 6;

@Test
public void createsFormData() {
    String html = "<form><input name='one' value='two'><select name='three'><option value='not'>" +
            "<option value='four' selected><option value='five' selected><textarea name=six>seven</textarea>" +
            "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>" +
            "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>" +
            "<input name='ten' value='text' disabled>" +
            "<input name='eleven' value='text' type='button'>" +
            "</form>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    List<Connection.KeyVal> data = form.formData();

    assertEquals("Form data size should be " + EXPECTED_FORM_DATA_COUNT,
            EXPECTED_FORM_DATA_COUNT, data.size());

    String kv0 = data.get(0).toString();
    assertEquals("First key‑value pair should be 'one=two'", "one=two", kv0);

    String kv1 = data.get(1).toString();
    assertEquals("Second key‑value pair should be 'three=four'", "three=four", kv1);

    String kv2 = data.get(2).toString();
    assertEquals("Third key‑value pair should be 'three=five'", "three=five", kv2);

    String kv3 = data.get(3).toString();
    assertEquals("Fourth key‑value pair should be 'six=seven'", "six=seven", kv3);

    String kv4 = data.get(4).toString();
    assertEquals("Fifth key‑value pair should be 'seven=on' (checked radio)", "seven=on", kv4);

    String kv5 = data.get(5).toString();
    assertEquals("Sixth key‑value pair should be 'eight=on' (default checked checkbox)", "eight=on", kv5);
    // nine should not appear, not checked checkbox
    // ten should not appear, disabled
    // eleven should not appear, button
}

