private static final int EXPECTED_VISIBLE_ATTRIBUTE_COUNT = 2;

private Attributes createAttributes() {
    Attributes a = new Attributes();
    a.put("One", "One");
    a.put(Attributes.internalKey("baseUri"), "example.com");
    a.put("Two", "Two");
    a.put(Attributes.internalKey("another"), "example.com");
    return a;
}

private int countAttributes(Attributes attrs) {
    int count = 0;
    for (Attribute attr : attrs) {
        count++;
    }
    return count;
}

@Test
public void testIteratorSkipsInternal_orderAndKeys() {
    Attributes a = createAttributes();
    Iterator<Attribute> it = a.iterator();

    assertTrue(it.hasNext(), "Iterator should have a next element before first call");
    Attribute first = it.next();
    assertEquals("One", first.getKey(), "First visible attribute key should be 'One'");

    assertTrue(it.hasNext(), "Iterator should have a next element before second call");
    Attribute second = it.next();
    assertEquals("Two", second.getKey(), "Second visible attribute key should be 'Two'");

    assertFalse(it.hasNext(), "Iterator should have no more visible elements after reading expected keys");
}

@Test
